import{_ as o}from"./chunks/micronav.BCQjLXCD.js";import{_ as t,o as a,c as r,al as n}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"Налаштування пульта","description":"","frontmatter":{},"headers":[],"relativePath":"uk/config/joystick.md","filePath":"uk/config/joystick.md"}'),i={name:"uk/config/joystick.md"};function s(c,e,l,p,m,d){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="налаштування-пульта" tabindex="-1">Налаштування пульта <a class="header-anchor" href="#налаштування-пульта" aria-label="Permalink to &quot;Налаштування пульта&quot;">​</a></h1><p>A <a href="https://en.wikipedia.org/wiki/Joystick" target="_blank" rel="noreferrer">computer joystick</a> or gamepad connected through <em>QGroundControl</em> can be used to manually control the vehicle (<em>instead</em> of using an <a href="./../config/radio">RC Transmitter</a>).</p><p>This approach may be used by manual control units that have an integrated ground control station (like the <em>UAVComponents</em> <a href="https://www.uxvtechnologies.com/ground-control-stations/micronav" target="_blank" rel="noreferrer">MicroNav</a> shown below). Джойстики також часто використовуються для того, щоб дозволити розробникам літати на транспортному засобі у симуляції.</p><p><img src="'+o+'" alt="Joystick MicroNav"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../config/radio">Radio Setup</a> is not required if using only a joystick (because a joystick is not an RC controller)!</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><em>QGroundControl</em> uses the cross-platform <a href="https://www.libsdl.org/index.php" target="_blank" rel="noreferrer">SDL2</a> library to convert joystick movements to MAVLink <a href="https://mavlink.io/en/messages/common.html#MANUAL_CONTROL" target="_blank" rel="noreferrer">MANUAL_CONTROL</a> messages, which are then sent to PX4 over the telemetry channel. В результаті система керування на основі джойстика потребує надійного телеметричного каналу високої пропускної здатності, щоб забезпечити реагування транспортного засобу на рухи джойстика.</p></div><h2 id="увімкнення-підтримки-джоистика-px4" tabindex="-1">Увімкнення підтримки джойстика PX4 <a class="header-anchor" href="#увімкнення-підтримки-джоистика-px4" aria-label="Permalink to &quot;Увімкнення підтримки джойстика PX4&quot;">​</a></h2><p>Information about how to set up a joystick is covered in: <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/joystick.html" target="_blank" rel="noreferrer">QGroundControl &gt; Joystick Setup</a>.</p><p>Підсумовуючи:</p><ul><li>Open <em>QGroundControl</em></li><li><a href="./../config/manual_control#px4-configuration">Enable a <code>COM_RC_IN_MODE</code> mode that allows Joystick</a>. The default <code>RC or MAVLink keep first</code> should work if you plan to only have a Joystick connected.</li><li>Підключіть джойстик</li><li>Configure the connected joystick in: <strong>Vehicle Setup &gt; Joystick</strong>.</li></ul>',10)])])}const f=t(i,[["render",s]]);export{k as __pageData,f as default};
